(()=>{'use strict';
const root=document.querySelector('.rg');if(!root)return;
const toc=root.querySelector('.rg-toc details');if(toc&&matchMedia('(max-width:1000px)').matches)toc.open=false;
const dialog=document.querySelector('.rg-dialog');let trigger=null;
root.querySelectorAll('[data-rg-image]').forEach(link=>link.addEventListener('click',e=>{if(!dialog||typeof dialog.showModal!=='function')return;e.preventDefault();trigger=link;const image=dialog.querySelector('img');image.src=link.href;image.alt=link.querySelector('img').alt;dialog.querySelector('p').textContent=link.closest('figure').querySelector('figcaption').textContent;dialog.showModal();}));
if(dialog){dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>trigger?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
const tool=root.querySelector('[data-rg-checklist]');if(tool){const checks=[...tool.querySelectorAll('input[type="checkbox"]')],status=tool.querySelector('[role="status"]');function update(){const n=checks.filter(c=>c.checked).length;status.textContent=n+' of '+checks.length+' checks marked. '+(n===checks.length?'Your list is complete; this is not a compatibility guarantee.':'Use the remaining checks before choosing an offer.');}checks.forEach(c=>c.addEventListener('change',update));tool.querySelector('[data-rg-reset]').addEventListener('click',()=>{checks.forEach(c=>c.checked=false);update();});tool.querySelector('[data-rg-export]').addEventListener('click',()=>{const title=root.querySelector('h1').textContent,text=title+'\n'+checks.map(c=>(c.checked?'[x] ':'[ ] ')+c.nextElementSibling.textContent).join('\n')+'\n\nSource: '+document.querySelector('link[rel="canonical"]').href+'\nPersonal checklist; not a product test or compatibility certification.\n',url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=tool.dataset.slug+'-checklist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);});update();}
root.querySelectorAll('a[data-affiliate]').forEach(a=>a.addEventListener('click',()=>{if(typeof window.gtag==='function')window.gtag('event','affiliate_click',{article:root.dataset.article,product:a.dataset.affiliate,link_type:'model_search'});}));
})();
